-- 112 启用 091 已登记的 AI Admin Web 菜单，并补齐阶段五页面权限；forward-only、幂等。
SET @ai_group_id=(SELECT `id` FROM `fun_permission` WHERE `source_type`='admin_web' AND `source_name`='ai_development' AND `resource_type`='group' ORDER BY `id` LIMIT 1);
SET @ai_view_id=(SELECT `id` FROM `fun_permission` WHERE `code`='console/development.ai:conversationindex' ORDER BY `id` LIMIT 1);
UPDATE `fun_admin_menu` SET `pid`=COALESCE((SELECT `id` FROM (SELECT `id` FROM `fun_admin_menu` WHERE `source_type`='admin_web' AND `source_name`='development_tools' ORDER BY `id` LIMIT 1) development_menu),0),`permission_id`=@ai_view_id,`app_name`='console',`name`=CONVERT(X'E699BAE883BDE5BC80E58F91E58AA9E6898B' USING utf8mb4),`href`='/development/ai',`query`='component=development/ai/index&name=AiDevelopment&type=C&permission=development:ai:view',`target`='_self',`icon`='i-ep-cpu',`status`=1,`updated_at`=NOW(),`sort_order`=30,`deleted_at`=NULL WHERE `source_type`='admin_web' AND `source_name`='ai_development' AND `href`='/development/ai';
